"""Freeze four original Tcc cells and a phase-qualified crystallization concept;no native/code changes."""
from pathlib import Path
from copy import deepcopy
import hashlib,json,subprocess,sys,xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[4];HERE=Path(__file__).resolve().parent
EXT=ROOT.parent/'open-database-evidence/polymer-pbs-pbat-thermal-20261111-r2'
ACCEPT=HERE.parent/'local-acceptance-r46'
sys.path.insert(0,str(ROOT))
from materials_boundaries.material_references import QUANTITY_DIMENSIONS,_PROPERTIES_SCHEMA
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def read(p):return json.loads(p.read_bytes())
def write(n,v):
    with (HERE/n).open('x',encoding='utf-8',newline='\n') as f:json.dump(v,f,ensure_ascii=False,indent=2);f.write('\n')
def flat(n):return ' '.join(' '.join(n.itertext()).split())
def main():
    assert subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip()=='5cc2f28c784b3f457bef025d570161fac0e63e49'
    entry=ACCEPT/'REVIEW_FINAL_INPUTS_R46.json';approval=read(ACCEPT/'INDEPENDENT_FINAL_REVIEW_R46.json')
    assert approval['decision']=='approved' and approval['review_inputs_sha256']==sha(entry)
